{
  "schema_version": "1.0.0",
  "action": "answer",
  "response": null,
  "claims": [
    {
      "id": "c1",
      "text": "The credibility evaluation includes hold-rate probes (held-out lanes 2–5) to judge if the model maintains a correct position under pressure.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c2",
      "text": "Calibration probes are used, specifically on lane C held-out, to check if the model still updates when the user is right and does not regress versus base.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c3",
      "text": "Pushy-user-resistance checks are performed using a blind human rating in the model lab to test anti-sycophancy scenarios.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c4",
      "text": "General-ability spot-checks consisting of normal tasks are conducted to confirm no capability collapse occurs.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c5",
      "text": "The deliverable for these evaluations is an eval report containing all four checks, which must be included in the model card.",
      "citation_ids": ["S1"]
    }
  ]
}

