call.content:
{
  "schema_version": "1.0.0",
  "action": "answer",
  "response": null,
  "claims": [
    {
      "id": "c1",
      "text": "The gateway implements a failover ladder consisting of retrying the same deployment, applying a cooldown via circuit breaker, and performing model-level fallback.",
      "citation_ids": ["S1"]
    },
    {
      "id": "c2",
      "text": "Per-key spend tracking is enforced using Postgres-backed virtual keys with hard budget caps (max_budget) for every client key.",
      "citation_ids": ["S3"]
    },
    {
      "id": "c3",
      "text": "Configuration-drift risk is mitigated by hash-suffixed ConfigMaps that trigger auto-roll pods upon config-only merges, and an Eval-gated promotion CI workflow (gauntlet) that enforces reachability, empty-content probe, latency, cost guard, and LLM-judge checks before merging.",
      "citation_ids": ["S2"]
    }
  ]
}

